#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

struct Node *push(struct Node *head, int value) {
    struct Node *node = malloc(sizeof(struct Node));
    node->value = value;
    node->next = head;
    return node;
}

struct Node *reverse(struct Node *head) {
    struct Node *prev = NULL;
    while (head != NULL) {
        struct Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

int main() {
    struct Node *list = NULL;
    for (int v = 4; v >= 1; v--) {
        list = push(list, v);
    }
    list = reverse(list);
    for (struct Node *p = list; p != NULL; p = p->next) {
        printf("%d ", p->value);
    }
    printf("\n");
    return 0;
}
